export const BODY: string = "\n<p>ضبط التشبع يستغرق بضع دقائق فقط. ترفع الصورة وتسحب منزلقًا وتراجع الألوان وتنزّل النسخة الأكثر حيوية.</p>\n<p>هذا البرنامج التعليمي يمر بالعملية كاملة خطوة بخطوة. يغطي المنزلق والإعدادات السريعة ونغمات البشرة وضبط التصدير التي تبقي الألوان بمظهر طبيعي.</p>\n<p>في النهاية ستستطيع إصلاح مشهد باهت أو تلطيف صورة صارخة أو تحويل صورة شخصية ملونة إلى أبيض وأسود نظيف، على أي جهاز. واحتفظ بالصورة الأصلية حتى تراجع النتيجة.</p>\n<h2 id=\"before-you-start\">قبل أن تبدأ: احكم على الألوان</h2>\n<p>انظر إلى الصورة قبل فتح الأداة. هل الألوان باهتة أم حية أم صارخة؟ الجواب يخبرك بأي اتجاه تحرك المنزلق.</p>\n<p>صورة باهتة تحتاج دفعة موجبة 10 إلى 25 بالمئة. صورة صارخة تحتاج حركة سالبة لإرجاع الألوان نحو الطبيعي. وراجع إن كانت الصورة داكنة جدًا أو مسطحة جدًا أيضًا: صورة باهتة وداكنة تحتاج سطوعًا أولًا، لأن التشبع وحده لا يستطيع إصلاح المستوى.</p>\n<p>افتح <a href=\"/ar/taadil-tashabbu-as-sura/\">محرر تشبع الصور</a> في متصفحك. كل شيء يعمل محليًا، فصورتك لا تُرفع أبدًا إلى خادم.</p>\n<h2 id=\"step-by-step\">اضبط التشبع في خمس خطوات</h2>\n<p>العملية نفسها لصورة أو لقطة شاشة أو صورة ممسوحة ضوئيًا. ارفع الصورة واضبط وراجع الألوان وصدّر وتحقق من التنزيل.</p>\n<p>خذ وقتك مع المنزلق. الحركات الصغيرة تصنع فرقًا كبيرًا، والمعاينة تُظهر لك بالضبط متى تبدو الألوان جيدة. وافتح الملف المنزّل مرة قبل استخدامه، وتأكد من أن الألوان تبدو طبيعية وحية دون أن تصبح نيون أو برتقالية.</p>\n<ol>\n<li>ارفع صورتك بسحبها إلى منطقة الرفع أو اختيارها من جهازك أو لصق لقطة شاشة بـCtrl+V.</li>\n<li>اسحب منزلق مستوى التشبع إلى اليمين لتعزيز الألوان أو إلى اليسار لإخفاتها، مراقبًا المعاينة الحية.</li>\n<li>جرّب إعدادًا سريعًا مثل باهت أو رمادي أو فائق لاختبار بنقرة واحدة، ثم دقّق بالمنزلق.</li>\n<li>راجع نغمات البشرة وأوراق الشجر والسماء بالحجم الكامل لتأكيد أن لا لون يبدو اصطناعيًا.</li>\n<li>اختر صيغة التصدير والجودة، ثم اضغط تنزيل لحفظ الصورة المعدلة.</li>\n</ol>\n<h2 id=\"using-the-slider\">كيف تستخدم منزلق التشبع</h2>\n<p>يتراوح المنزلق من -100 إلى +100 بالمئة، مع الصفر كلا تغيير. تحريكه إلى اليمين يعزز الألوان، وتحريكه إلى اليسار يجففها.</p>\n<p>اسحب ببطء وراقب المعاينة. التحديث الحي يُظهر بالضبط كيف تستجيب الألوان، فتستطيع التوقف عند النقطة التي تبدو فيها الصورة طبيعية. والحركات الصغيرة أفضل من الكبيرة: تغيير 10 إلى 25 بالمئة غالبًا يكفي، والحركات الأكبر تجعل الألوان تبدو اصطناعية بسرعة.</p>\n<p>تُظهر الأداة صورتك بـ+25 بالمئة فور رفعها. نقطة البداية هذه تعطيك فكرة فورية عن مظهر زيادة تشبع معتدلة.</p>\n<h2 id=\"using-quick-presets\">كيف تستخدم الإعدادات السريعة</h2>\n<p>تضم الأداة إعدادات سريعة بنقرة واحدة تطبق قيم تشبع شائعة فورًا. إنها طريقة سريعة لتجربة مظاهر مختلفة دون سحب المنزلق.</p>\n<p>باهت، بـ-40 بالمئة، يلطّف الألوان لمظهر هادئ وأنيق. رمادي، بـ-100 بالمئة، يزيل كل الألوان لصورة أبيض وأسود. وفائق، بـ+90 بالمئة، يدفع الألوان إلى حدها: يناسب الملصقات والرسوم المنمقة، لكنه نادرًا ما يناسب التصوير الطبيعي.</p>\n<p>اضغط إعدادًا سريعًا وراقب المعاينة. إذا كانت النتيجة قريبة لكنها ليست جيدة تمامًا، دقّق بالمنزلق من تلك النقطة.</p>\n<h2 id=\"boosting-a-dull-photo\">كيف تعزز صورة باهتة</h2>\n<p>ارفع الصورة الباهتة واسحب المنزلق إلى +20 بالمئة. راجع المعاينة: يجب أن تبدو الألوان أغنى، بأخضر أعمق وسماء أزرق، دون أن تبدو زائفة.</p>\n<p>إذا بقيت الصورة باهتة، زد المنزلق بخطوات صغيرة 5 بالمئة. كل خطوة تضيف قليلًا من الحيوية، والمعاينة تُظهر متى تتوقف. وراقب أوراق الشجر وأنت تتقدم: العشب والأوراق تصبح نيون أولًا، ومشهد بحقول خضراء ساطعة يبدو اصطناعيًا.</p>\n<p>إذا بدت الصورة صارخة بعد تعزيزها، اخفض المنزلق 5 بالمئة. تخفيض صغير غالبًا يستعيد المظهر الطبيعي دون فقدان الحيوية.</p>\n<h2 id=\"muting-a-harsh-photo\">كيف تخفت صورة قاسية وصارخة</h2>\n<p>اسحب المنزلق إلى اليسار لصورة ألوانها قوية جدًا. قيم سالبة مثل -20 أو -40 بالمئة تلطّف لوحة الألوان إلى مظهر أهدأ.</p>\n<p>راجع البشرة وأنت تخفت: يجب أن يبدو الوجه طبيعيًا وناعمًا، لا رماديًا وبلا حياة، فتوقف قبل أن تختفي الألوان تمامًا. والإخفات يناسب الأعراس والصور الشخصية والفن، حيث لوحة ألوان ناعمة تبدو أنيقة: صورة مخففة بألوان ناعمة تبدو راقية، بينما صورة صارخة تبدو صاخبة.</p>\n<p>ولمظهر مخفف تمامًا، استخدم الإعداد السريع رمادي بـ-100 بالمئة: تصبح الصورة أبيض وأسود، ما يناسب المشاهد الدرامية والصور الشخصية الخالدة.</p>\n<h2 id=\"converting-to-grayscale\">كيف تحول إلى رمادي بنقرة واحدة</h2>\n<p>اضغط الإعداد السريع رمادي لإزالة كل لون من الصورة في خطوة واحدة. تصبح الصورة أبيض وأسود، ويبقى السطوع والتباين فقط ليحملاها.</p>\n<p>يناسب الرمادي المشاهد الدرامية والعمارة وتصوير الشارع، حيث الشكل والضوء أهم من اللون. ويناسب أيضًا الصور الشخصية ذات التعابير القوية. وبعد التحويل، راجع التباين: صورة رمادية غالبًا تحتاج دفعة تباين صغيرة، لأن اللون كان يحمل جزءًا من العمق الذي ذهب الآن.</p>\n<p>صدّر الصور الرمادية كـJPG بضبط جودة عالية، أو PNG لأحدة نتيجة. الصيغة أقل أهمية من التباين، الذي يحدد المظهر الأبيض والأسود.</p>\n<h2 id=\"fixing-skin-tones\">كيف تصلح نغمات البشرة</h2>\n<p>البشرة أصعب ما يُشبع بشكل صحيح. دفعة صغيرة قد تجعل صورة شخصية تبدو صحية، لكن دفعة كبيرة تجعل البشرة برتقالية أو حمراء أو صفراء.</p>\n<p>ابدأ بزيادة صغيرة 10 إلى 15 بالمئة للصور الشخصية. راجع الوجه: يجب أن تبدو البشرة دافئة وطبيعية، لا كأن الشخص قضى وقتًا طويلًا جدًا في الشمس. وراقب الخدين والجبهة، فهما يُظهران الإفراط في التشبع أولًا: وجه بخدين برتقاليين وجبهة صفراء دُفع بعيدًا جدًا.</p>\n<p>إذا بدت البشرة برتقالية بعد تعزيزها، اخفض المنزلق 5 بالمئة وراجع مجددًا: التخفيضات الصغيرة غالبًا تستعيد النغمة الطبيعية دون فقدان التوهج الصحي.</p>\n<h2 id=\"previewing\">المعاينة قبل التنزيل</h2>\n<p>راجع المعاينة دائمًا قبل التنزيل. تحقق من أن الألوان تبدو طبيعية، وأن لا منطقة أصبحت نيون، وأن نغمات البشرة دافئة لا برتقالية.</p>\n<p>قرّب على أوراق الشجر والسماء والبشرة بالحجم الكامل: هذه المناطق تُظهر الإفراط في التشبع أولًا، وقد تخفي معاينة صغيرة المشكلة. وراجع الصورة على شاشة ثانية إن استطعت: الألوان تبدو مختلفة على شاشات مختلفة، ومراجعة ثانية تكتشف مفاجآت قبل مشاركة الصورة.</p>\n<p>إذا بدا أي لون اصطناعيًا، اخفض المنزلق 5 بالمئة وراجع مجددًا: التخفيضات الصغيرة غالبًا تستعيد المظهر الطبيعي دون فقدان الحيوية.</p>\n<h2 id=\"choosing-export-format\">كيف تختار صيغة التصدير</h2>\n<p>اختر JPG للصور التي تنوي مشاركتها. يبقي الملفات صغيرة ويعمل في كل مكان، وضبط جودة عالية يبقي الألوان نظيفة.</p>\n<p>اختر PNG للرسوم والملصقات ذات الشفافية: لا يفقد PNG شيئًا، فتبقى الألوان دقيقة، ويحافظ على المناطق شبه الشفافة. واختر WebP عندما تريد ملفات صغيرة بجودة جيدة: يعمل جيدًا لصور الويب، مع أن بعض الأنظمة القديمة ما زالت ترفض الصيغة.</p>\n<p>تذكر أن ضبط الجودة يُخفى لـPNG، لأن PNG دون فقدان وليس له ضبط جودة لتغييره. هذا سلوك طبيعي، لا مشكلة في الأداة.</p>\n<h2 id=\"adjusting-on-mobile\">كيف تضبط التشبع على الهاتف أو الجهاز اللوحي</h2>\n<p>تعمل الأداة على شاشات اللمس، فتستطيع إصلاح صورة باهتة على الهاتف نفسه الذي التقطها. ارفع الصورة من معرضك واسحب المنزلق بإصبعك ونزّل النتيجة.</p>\n<p>سحب منزلق بالإصبع أقل دقة من الفأرة: استخدم الإعدادات السريعة لقيم دقيقة، ثم دقّق بسحبات صغيرة. وراجع المعاينة بالحجم الكامل قبل التنزيل: تغيير تشبع يبدو جيدًا على شاشة هاتف صغيرة قد يكون قويًا جدًا عند رؤيته على حاسوب.</p>\n<p>تُحفظ الملفات المنزّلة في مجلد التنزيلات المعتاد لديك. ومن هناك يمكنك مشاركة الصورة المعدلة مباشرة إلى تطبيق محادثة أو بريد أو منشور اجتماعي.</p>\n<h2 id=\"troubleshooting\">كيف تحل مشاكل التشبع الشائعة</h2>\n<p>إذا بدت الصورة صارخة، فالمنزلق مرتفع جدًا. اخفضه بخطوات صغيرة حتى يبدو العشب والسماء والبشرة طبيعية مجددًا.</p>\n<p>وإذا بقيت الصورة باهتة بعد تعزيزها، فقد يكون الأصل مسطحًا جدًا لإنقاذه: صورة التُقطت عبر ضباب كثيف لا تستطيع اكتساب لون لم يُسجل أبدًا. وإذا بدت البشرة برتقالية، اخفض التشبع وراجع الوجه بالحجم الكامل: تخفيض صغير غالبًا يستعيد النغمة الطبيعية.</p>\n<p>وإذا بدت المعاينة مختلفة عن التنزيل، راجع صيغة التصدير والجودة: ضبط جودة JPG منخفض قد يغيّر الألوان قليلًا، خصوصًا في المناطق الفاتحة.</p>\n<h2 id=\"saturation-plus-contrast\">تشبع مع تباين: الثنائي الشائع</h2>\n<p>صورة باهتة ومسطحة تحتاج تشبعًا وتباينًا معًا. عزز الألوان أولًا، ثم أضف تباينًا لاستعادة العمق.</p>\n<p>استخدم <a href=\"/ar/taadil-tabayun-as-sura/\">محرر تباين الصور</a> بعد التشبع، عندما تبدو الصورة حية لكنها ما زالت مسطحة: دفعة تباين صغيرة تعيد الظلال والأضواء. واعمل الخطوات بالترتيب: تشبع أولًا ثم تباين. عكسهما قد يجعل الحكم على تغيير اللون أصعب، لأن الصورة ما زالت مسطحة.</p>\n<p>راجع الألوان بعد كل خطوة: دفعة تباين تجعل الألوان أغنى أيضًا، فقد يحتاج التشبع تخفيضًا صغيرًا بعدها.</p>\n<h2 id=\"saturation-for-social\">تشبع للتواصل الاجتماعي</h2>\n<p>خلاصات التواصل الاجتماعي تفضل الصور الحية والواضحة. صورة باهتة تُتخطى، بينما صورة مشبعة جيدًا توقف الإبهام وتكسب نظرة ثانية.</p>\n<p>عزز الصور الاجتماعية قليلًا أكثر مما تفعل للطباعة: الشاشات تختلف في اللون، وصورة تبدو جيدة على هاتفك قد تبدو باهتة على هاتف شخص آخر. وأبقِ الدفعة طبيعية: صورة دُفعت بعيدًا جدًا تبدو اصطناعية، والمتابعون يلاحظون عندما لا تطابق الألوان المشهد.</p>\n<p>اختبر الصورة المشبعة بحجم الخلاصة قبل النشر: صورة تبدو جيدة بالحجم الكامل قد تبدو باهتة جدًا أو صارخة جدًا في معاينة صغيرة، فراجع قبل النشر.</p>\n<h2 id=\"saving-settings\">كيف تحفظ ضبطك للمرة القادمة</h2>\n<p>دوّن قيمة التشبع التي نجحت لمجموعة صور متشابهة. ملاحظة قصيرة، مثل مشاهد +20 بالمئة، توفر عليك التخمين في المرة القادمة.</p>\n<p>ولدفعة صور التُقطت بنفس الضوء، استخدم نفس القيمة لكلها: لون متسق عبر مجموعة يبدو احترافيًا، بينما القيم المختلطة تبدو عشوائية. واحتفظ بالملفات الأصلية: قيمة تشبع تناسب صورة قد لا تناسب أخرى، والأصل يتيح لك تجربة مستوى مختلف دون ضرر إضافي.</p>\n<p>راجع ملاحظاتك من حين لآخر. مع تحسن كاميرتك وإضاءتك، ستتغير قيم التشبع التي تحتاجها، وقد تضللك الملاحظات القديمة.</p>\n<h2 id=\"quick-tips\">نصائح سريعة لتشبع أفضل</h2>\n<p>اضبط بخطوات صغيرة. تغيير 5 بالمئة في كل مرة يمنحك تحكمًا، بينما قفزة كبيرة قد تتجاوز القيمة الصحيحة قبل أن تلاحظ.</p>\n<p>راجع البشرة، لا المشهد فقط: دفعة مشهد تبدو جيدة على العشب قد تجعل الأشخاص في الصورة برتقاليين. واستخدم الإعدادات السريعة كنقطة بداية: إعداد سريع يمنحك اختبارًا سريعًا، والمنزلق يتيح لك الضبط الدقيق من هناك.</p>\n<p>احفظ الصورة الأصلية دون تعديل. بمجرد أن يُدمج تغيير تشبع في تصدير، لا يمكن التراجع عنه من ذلك الملف.</p>\n<h2 id=\"saturation-for-sunset\">كيف تضبط التشبع لصورة غروب</h2>\n<p>صور الغروب ملونة أصلًا، فهي تحتاج فقط دفعة صغيرة. زيادة تشبع 10 إلى 15 بالمئة تعمّق البرتقالي والوردي دون أن تجعل السماء تبدو مرسومة.</p>\n<p>راقب تدرج السماء وأنت تعزز: سماء غروب يجب أن تتلاشى بنعومة من برتقالي إلى وردي إلى أزرق، ودفعة قوية قد تحول ذلك التدرج إلى كتل لون مسطحة. وراجع المقدمة بعد التعزيز: مقدمة داكنة بألوان معززة قد تبدو ضبابية، ففتّحها قليلًا أولًا إن كان الغروب هو الموضوع الرئيسي.</p>\n<p>ولغروب فوق الماء، دفعة معتدلة تعزز الانعكاس دون جعله صارخًا: يجب أن يعكس الماء السماء، لا أن ينافسها.</p>\n<p>للمقارنة، اقرأ <a href=\"/ar/blog/tashabbu-vs-hayawiyya/\">تشبع أم حيوية: تعديل لوني طبيعي</a>. وللدليل الكامل، راجع <a href=\"/ar/blog/dalil-muharrir-tashabbu-as-suwar/\">دليل محرر تشبع الصور الكامل</a>، ولإضافة مظهر متسق عبر دفعة جرّب <a href=\"/ar/murashshahat-as-suwar/\">مرشحات الصور</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أعزز لون صورة على هاتفي؟","answer":"افتح محرر تشبع الصور في متصفح هاتفك وارفع الصورة من معرضك واسحب المنزلق إلى اليمين بإصبعك. واستخدم إعدادًا سريعًا لقيمة دقيقة، وراجع نغمات البشرة ونزّل النتيجة."},{"question":"أي قيمة تشبع يجب أن أستخدم لصورة مشهد؟","answer":"ابدأ بـ+20 بالمئة وراجع أوراق الشجر. المشاهد غالبًا تحتاج 20 إلى 30 بالمئة لتبدو حية. وتوقف قبل أن يصبح العشب نيون أو تبدو السماء مرسومة، واخفض المنزلق إن بدت الألوان اصطناعية."},{"question":"كيف أحول صورة ملونة إلى أبيض وأسود؟","answer":"اضغط الإعداد السريع رمادي، الذي يثبت التشبع عند -100 بالمئة ويزيل كل الألوان في خطوة واحدة. وراجع التباين بعدها، إذ تحتاج صورة رمادية غالبًا دفعة تباين صغيرة."},{"question":"لماذا تبدو صورة طعامي زائفة بعد تعزيز التشبع؟","answer":"المنزلق مرتفع جدًا، ما يجعل الأحمر ساطعًا بشكل غير طبيعي والأخضر نيون. الطعام يحتاج فقط دفعة صغيرة 10 إلى 20 بالمئة. اخفض المنزلق حتى يبدو الطبق طازجًا وجذابًا."},{"question":"هل أضبط التشبع قبل التباين أم بعده؟","answer":"التشبع أولًا ثم التباين. تعزيز الألوان يغيّر إحساس الصورة، والتباين يضبط العمق بعدها. وراجع الألوان مجددًا بعد تغيير التباين، إذ يجعلها أغنى أيضًا."},{"question":"هل يمكنني التراجع عن تغيير تشبع بعد التنزيل؟","answer":"لا من الملف المنزّل، إذ يُدمج التغيير في التصدير. احتفظ بالصورة الأصلية لتستطيع تجربة مستوى تشبع آخر. وفي الأداة، استخدم خيار إعادة الضبط للعودة إلى الصفر قبل التنزيل."}];
